page.customCss:
@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700&family=Sora:wght@400;600&family=Inter:wght@400;600;700&display=swap');

html,body{overflow-x:hidden;scroll-behavior:smooth}
*{box-sizing:border-box;font-family:Montserrat,sans-serif}

/* ── HEADER ─────────────────────────────── */
.mw-header{background:#fff;box-shadow:rgba(106,115,129,.16) 0 6px 12px,rgba(106,115,129,.06) 0 3px 8px;padding:8px 0;position:sticky;top:0;z-index:100}
.mw-header .mw-container{width:90%;max-width:1210px;margin:0 auto;display:flex;justify-content:space-between;align-items:center}
.mw-header .mw-left{display:flex;gap:24px;align-items:center}
.mw-logo{color:#ff0000!important;font-size:20px;font-weight:700;line-height:1}
.mw-nav{display:flex;gap:24px;align-items:center}
.mw-nav a{font-size:14px;font-weight:600;color:#586571;text-decoration:none;white-space:nowrap}
.mw-nav a:hover{text-decoration:underline}
.mw-right{display:flex;gap:24px;align-items:center}
.mw-right a{font-size:14px;font-weight:600;color:#586571;text-decoration:none;white-space:nowrap}
.mw-signin{border:1px solid #D8D8D8;border-radius:8px;font-size:14px;font-weight:700;background:none;padding:8px 12px;color:#586571;cursor:pointer;font-family:Montserrat,sans-serif}

/* ── MAIN / VSL ──────────────────────────── */
.mw-main{padding:40px 0}
.mw-container{width:90%;max-width:900px;margin:0 auto}
.mw-meta{display:grid;gap:8px;color:#6e6e6e;font-size:14px;margin-bottom:16px}
.mw-meta span{display:flex;align-items:center;gap:6px}
.mw-h1{font-size:30px;font-weight:700;color:#374151;margin:0 0 18px;line-height:1}
.mw-h1 b{color:#ff0000!important}
.mw-sub{font-size:20px;color:#374151;margin:0 0 16px}
.mw-video-wrap{width:100%;margin-bottom:12px}
.mw-viewer{text-align:center;background:rgba(220,53,69,.1);padding:10px;border-radius:8px;max-width:400px;margin:16px auto 20px;font-weight:600;font-size:14px;color:#C41E3A}
.mw-viewer span{color:#000}

/* ── PROMO BANNER ────────────────────────── */
.mw-banner{background:#031E69;border-top:4px solid #D4A84F;padding:40px 0}
.mw-banner .mw-inner{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px}
.mw-banner h1{color:#fff;font-size:40px;line-height:1;max-width:30ch;margin:0 0 24px;font-weight:700}
.mw-banner .mw-countdown{font-size:54px;color:#FFF702;font-weight:700;display:block;font-family:Montserrat,sans-serif}
.mw-arrow{color:#fff;font-size:32px;margin-top:12px}

/* ── AREA-KITS ───────────────────────────── */
.mw-kits{padding:80px 0}
.mw-kits-inner{width:95%;max-width:1210px;margin:0 auto}
.mw-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:32px;align-items:flex-end}
.mw-card{border-radius:20px;overflow:hidden;border:1px solid rgba(13,42,69,.4);background:#fff;transition:transform .6s;display:block;text-decoration:none;color:inherit}
.mw-card:hover{transform:scale(1.01)}
.mw-card-header{background:#021956;color:#fff;font-size:20px;font-weight:400;text-transform:uppercase;padding:16px;text-align:center;border-radius:20px 20px 0 0}
.mw-card-main{padding:16px 12px 0;text-align:center}
.mw-card-qty{font-size:48px;font-weight:700;color:#021956;display:block;line-height:1.3}
.mw-card-days{font-size:20px;font-weight:400;color:#5e7885;margin-bottom:20px;display:block}
.mw-card-img{height:267px;object-fit:contain;display:block;margin:0 auto;position:relative;z-index:2}
.mw-area-img{position:relative}

