.mw-save b{font-size:13px;font-weight:700;color:#fff;display:block;line-height:1.2;text-align:center}
.mw-save b small{font-size:10px;font-weight:500;display:block}

.mw-card-footer{padding:0 16px 24px}
.mw-card-price{display:flex;align-items:flex-end;justify-content:center;margin-bottom:16px;padding-top:16px}
.mw-card-price strong{color:#021956;font-size:52px;font-weight:700}
.mw-card-price small{font-size:18px;font-weight:400;color:#5e7885;padding-bottom:6px}
.mw-best{border:2px solid #D4A84F;background:#FFEED9}
.mw-best .mw-card-header{background:linear-gradient(270deg,#A4823D 0%,#FFD580 25%,#FFD580 69%,#A4823D 100%);color:#021956;font-size:24px;font-weight:600}
.mw-best .mw-card-qty{color:#021956}
.mw-best .mw-card-price strong{font-size:58px}
.mw-garantias{list-style:none;padding:0;margin:0 0 16px;display:flex;flex-direction:column;gap:8px}
.mw-garantias li{display:flex;align-items:center;gap:8px;font-size:16px;color:#586571}
.mw-garantias li img{width:20px;height:20px}
.mw-btn-wrap{text-align:center;margin-bottom:8px}
.mw-btn-img{max-width:280px;width:100%;cursor:pointer;transition:transform .3s,filter .3s}
.mw-btn-img:hover{transform:translateY(-3px);filter:brightness(1.05)}
.mw-bandeiras{width:70%;display:block;margin:0 auto 12px}
.mw-valores{display:flex;justify-content:center;align-items:center;gap:8px;font-size:18px}
.mw-valores s{text-decoration:line-through;color:#6e7278;text-decoration-color:#C1121F}
.mw-valores b{color:#021956;font-weight:600}
.mw-valores span{color:#6e7278}
.mw-medalhas{display:flex;justify-content:center;align-items:center;gap:64px;flex-wrap:wrap;padding:20px 0 40px}
.mw-medalhas img{width:105px;height:105px;object-fit:contain}

/* ── GARANTIA ────────────────────────────── */
.mw-guarantee{display:flex;align-items:center;justify-content:center;gap:118px;padding:80px 71px;min-height:467px;border:1px solid #D6EEFF;overflow:hidden;position:relative;background:linear-gradient(135deg,#071623 0%,#0d2a45 50%,#071623 100%)}
.mw-guarantee-badge{width:289px;height:289px;object-fit:contain;position:relative;z-index:1}
.mw-guarantee-content{display:flex;flex-direction:column;gap:40px;width:607px;position:relative;z-index:1}
.mw-guarantee-h2{font-family:Sora,sans-serif;font-size:36px;font-weight:600;color:#fff;line-height:1.3;margin:0}
.mw-guarantee-h2 span{color:#D4A84F}
.mw-guarantee-p{font-family:Sora,sans-serif;font-size:18px;font-weight:400;color:#C1C1C1;line-height:1.6;margin:0}
.mw-guarantee-btn{display:flex;align-items:center;gap:12px;padding:18px 104px;background:linear-gradient(rgb(53,246,15),rgb(31,166,4));border-bottom:6px solid #116800;border-radius:50px;color:#fff;text-decoration:none;font-family:Inter,sans-serif;font-size:24px;font-weight:600;text-transform:uppercase;transition:filter .3s,transform .3s;align-self:flex-start}
.mw-guarantee-btn:hover{filter:brightness(1.1);transform:translateY(-1px)}
.mw-guarantee-btn:active{transform:translateY(1px);filter:brightness(.95)}
.mw-guarantee-btn img{width:24px;height:24px}

/* ── FOOTER ──────────────────────────────── */
.mw-footer{background:#021956}
.mw-footer-nav{display:flex;justify-content:center;align-items:center;gap:24px;padding:40px 0;flex-wrap:wrap}
.mw-footer-nav a{color:#fff;font-size:20px;text-decoration:none}
.mw-footer-nav a:hover{color:#D6EEFF;text-decoration:underline}
.mw-disclaimer{padding:24px 32px;border-radius:20px;border-top:1px solid #D6EEFF;text-align:center;color:#fff;font-size:16px;font-weight:400;max-width:1190px;margin:0 auto}
.mw-copy{background:#fff;padding:32px 5%;text-align:center;color:#0D2A45;font-size:14px}

/* ── RESPONSIVO ──────────────────────────── */
@media(max-width:1000px){.mw-right{display:none}.mw-nav{display:none}}
@media(max-width:900px){
  .mw-main{padding:20px 0}
  .mw-h1{font-size:20px;line-height:1.2}
  .mw-sub{font-size:16px}
  .mw-banner h1{font-size:26px}
  .mw-kits{padding:40px 0}
  .mw-grid{grid-template-columns:1fr;gap:24px}
  .mw-card-qty{font-size:24px}
  .mw-best .mw-card-price strong{font-size:36px}
  .mw-card-price strong{font-size:36px}
  .mw-card-img{height:auto;width:100%}
  .mw-garantias li{font-size:13px;white-space:nowrap}
  .mw-medalhas{gap:10px}
  .mw-medalhas img{width:50px;height:50px}
  .mw-guarantee{flex-direction:column;padding:60px 24px;gap:40px}
  .mw-guarantee-badge{width:200px;height:200px}
  .mw-guarantee-content{width:100%;align-items:center;text-align:center}
  .mw-guarantee-h2{font-size:28px}
  .mw-guarantee-p{font-size:16px}
  .mw-guarantee-btn{padding:16px 48px;font-size:20px}
  .mw-footer-nav a{font-size:16px}
  .mw-disclaimer{font-size:14px;padding:16px}
}
